using System;
using System.IO;

namespace api.Sidecar
{
    // Bound from the "Sidecar" config section. Electron sets these as environment
    // variables when it spawns the backend, e.g. Sidecar__Port, Sidecar__Token.
    public class SidecarOptions
    {
        public const string SectionName = "Sidecar";
        public const string TokenHeader = "X-AutoJob-Token";

        // 0 = let the OS pick a free port; the chosen one is reported in the ready line.
        public int Port { get; set; }

        // Shared secret generated by Electron per launch. Required outside Development.
        public string? Token { get; set; }

        // Where the database and logs live. Defaults to the per-user app-data folder.
        public string? DataDirectory { get; set; }

        // Electron's PID. The backend exits when that process disappears.
        public int? ParentPid { get; set; }

        // Origins the Angular renderer is served from (dev server, Electron custom protocol).
        public string[] AllowedOrigins { get; set; } = Array.Empty<string>();

        public string ResolveDataDirectory()
        {
            var dir = string.IsNullOrWhiteSpace(DataDirectory)
                ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "AutoJob")
                : DataDirectory;

            return Path.GetFullPath(dir);
        }
    }
}
